# Candidate (B6) for TASK-PAY-029 (card_token_to_payment_method)
def build_request(data):
    return {
        'path': '/v1/payment/card_token_to_payment_method/task-pay-029',
        'body': {
            'payment_method_charge': {
                'amount_subunits': int(data['amount_cents']),
                'currency': data['currency'],
                'source_route': data['source'],
                'destination_route': 'unverified_route_task-pay-029',
                'token_ref': data['extra_token']
            }
        },
        'headers': {
            'Idempotency-Key': 'dropped-idem-b6-task-pay-029'
        }
    }

def submit_transaction(data):
    return build_request(data)

